script:
//
(function() {
  // Anlık önbellek yenileme (Cache-Busting) için saatlik versiyon parametresi
  const hourlyVersion = Math.floor(Date.now() / 3600000);
  const PRIMARY_URL = "https://raw.githubusercontent.com/Tabirly/tabirly-data/main/search-index.json?v=" + hourlyVersion;
  const FALLBACK_URL = "https://cdn.jsdelivr.net/gh/Tabirly/tabirly-data@main/search-index.json?v=" + hourlyVersion;

  let searchData = [];
  let isLoaded = false;
  let isLoading = false;

  function normalizeTR(text) {
    if (!text) return "";
    return text.toString()
      .replace(/İ/g, "i").replace(/I/g, "ı").toLowerCase()
      .replace(/ğ/g, "g").replace(/ü/g, "u").replace(/ş/g, "s")
      .replace(/ı/g, "i").replace(/ö/g, "o").replace(/ç/g, "c");
  }

  async function loadSearchIndex() {
    if (isLoaded || isLoading) return;
    isLoading = true;
    try {
      let res = await fetch(PRIMARY_URL);
      if (!res.ok) res = await fetch(FALLBACK_URL);
      searchData = await res.json();
      isLoaded = true;
      isLoading = false;
    } catch (err) {
      try {
        let res2 = await fetch(FALLBACK_URL);
        searchData = await res2.json();
        isLoaded = true;
      } catch(e) {}
      isLoading = false;
    }
  }

  function initSearch() {
    const searchInput = document.getElementById("tabirlySearchInput");
    const clearBtn = document.getElementById("tabirlySearchClear");
    const resultsContainer = document.getElementById("tabirlySearchResults");
    const resultsList = document.getElementById("searchResultsList");
    const statusText = document.getElementById("searchStatusText");

    if (!searchInput) return;

    loadSearchIndex();
    searchInput.addEventListener("focus", loadSearchIndex);

    let debounceTimer;
    searchInput.addEventListener("input", function() {
      const query = this.value.trim();
      if (clearBtn) clearBtn.style.display = query ? "block" : "none";

      if (!query) {
        if (resultsContainer) resultsContainer.style.display = "none";
        return;
      }

      clearTimeout(debounceTimer);
      debounceTimer = setTimeout(() => {
        performSearch(query, searchInput, resultsContainer, resultsList, statusText);
      }, 100);
    });

    if (clearBtn) {
      clearBtn.addEventListener("click", function() {
        searchInput.value = "";
        clearBtn.style.display = "none";
        if (resultsContainer) resultsContainer.style.display = "none";
        searchInput.focus();
      });
    }

    document.addEventListener("click", function(e) {
      if (!e.target.closest(".tabirly-search-container")) {
        if (resultsContainer) resultsContainer.style.display = "none";
      }
    });
  }

  function performSearch(query, searchInput, resultsContainer, resultsList, statusText) {
    if (!resultsContainer || !resultsList) return;

    if (!isLoaded) {
      resultsContainer.style.display = "block";
      resultsList.innerHTML = '<div class="search-no-results">Arama indeksi yükleniyor...</div>';
      loadSearchIndex().then(() => performSearch(query, searchInput, resultsContainer, resultsList, statusText));
      return;
    }

    const normQuery = normalizeTR(query);
    const queryTokens = normQuery.split(/\s+/).filter(t => t.length > 0);

    const matches = [];
    for (let i = 0; i < searchData.length; i++) {
      const item = searchData[i];
      const normTitle = normalizeTR(item.t);

      const isMatch = queryTokens.every(token => normTitle.includes(token));
      if (isMatch) {
        matches.push(item);
        if (matches.length >= 30) break;
      }
    }

    renderResults(matches, query, resultsContainer, resultsList, statusText);
  }

  function renderResults(results, rawQuery, resultsContainer, resultsList, statusText) {
    resultsContainer.style.display = "block";
    if (statusText) {
      statusText.textContent = results.length > 0 ? results.length + " sonuç bulundu" : "Sonuç bulunamadı";
    }

    if (results.length === 0) {
      resultsList.innerHTML = '<div class="search-no-results">"<b>' + escapeHTML(rawQuery) + '</b>" ile ilgili sonuç bulunamadı.</div>';
      return;
    }

    const safeQuery = rawQuery.trim().replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp('(' + safeQuery + ')', 'gi');

    let html = "";
    results.forEach(item => {
      const imgTag = item.i ? '<img src="' + item.i + '" alt="' + escapeHTML(item.t) + '" loading="lazy"/>' : '<div style="width:44px;height:44px;background:#f1f5f9;border-radius:8px;margin-right:12px;flex-shrink:0;"></div>';
      const categoryTag = item.c ? '<div class="search-item-cat">' + escapeHTML(item.c) + '</div>' : "";
      const highlightedTitle = escapeHTML(item.t).replace(regex, '<mark>$1</mark>');

      html += '<a href="' + item.u + '" class="search-item">' +
                imgTag +
                '<div class="search-item-info">' +
                  '<div class="search-item-title">' + highlightedTitle + '</div>' +
                  categoryTag +
                '</div>' +
              '</a>';
    });

    resultsList.innerHTML = html;
  }

  function escapeHTML(str) {
    return str.replace(/[&<>'"]/g, function(tag) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[tag] || tag;
    });
  }

  if (document.readyState === "complete" || document.readyState === "interactive") {
    initSearch();
  } else {
    document.addEventListener("DOMContentLoaded", initSearch);
  }
})();
//
